# Stooorna - one-shot Android setup + build
# Put this file in the project root (the folder that has package.json and the android folder), then run:
#   powershell -ExecutionPolicy Bypass -File .\setup-stooorna-android.ps1

$ErrorActionPreference = 'Stop'
Set-Location $PSScriptRoot
function Step($m) { Write-Host ""; Write-Host "==> $m" -ForegroundColor Cyan }
$utf8 = New-Object System.Text.UTF8Encoding($false)

if (-not (Test-Path 'package.json')) { throw "package.json not found. Put this script in the project root and run it from there." }
if (-not (Test-Path 'android'))      { throw "android folder not found. Run 'npx cap add android' once from the project root, then run this script again." }

# ---------- 1. Capacitor config (server.url so login/API work) ----------
Step "1/6  Capacitor config"
if (Test-Path 'capacitor.config.ts') { Move-Item -Force 'capacitor.config.ts' 'capacitor.config.ts.bak'; Write-Host "capacitor.config.ts disabled (renamed to .bak)" }
if (Test-Path 'capacitor.config.js') { Move-Item -Force 'capacitor.config.js' 'capacitor.config.js.bak'; Write-Host "capacitor.config.js disabled (renamed to .bak)" }
$cfg = @'
{
  "appId": "com.stooorna.app",
  "appName": "Stooorna",
  "webDir": "dist/client",
  "backgroundColor": "#060E0E",
  "server": {
    "url": "https://stooorna.com",
    "androidScheme": "https",
    "cleartext": false,
    "allowNavigation": [
      "stooorna.com",
      "*.stooorna.com",
      "polar.sh",
      "*.polar.sh",
      "stripe.com",
      "*.stripe.com",
      "*.stripe.network"
    ]
  }
}
'@
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'capacitor.config.json'), $cfg, $utf8)
Write-Host "capacitor.config.json written"

