'@
$zip = Join-Path $env:TEMP 'stooorna-icons.zip'
[IO.File]::WriteAllBytes($zip, [Convert]::FromBase64String(($iconsB64 -replace '\s', '')))
Expand-Archive -Path $zip -DestinationPath 'android\app\src\main\res' -Force
Remove-Item $zip -Force
Write-Host "icons copied into android\app\src\main\res"

# ---------- 3. Android permissions (same list as the working APK) ----------
Step "3/6  Permissions in AndroidManifest.xml"
$mf = Join-Path $PSScriptRoot 'android\app\src\main\AndroidManifest.xml'
if (-not (Test-Path $mf)) { throw "AndroidManifest.xml not found at $mf" }
Copy-Item $mf "$mf.bak" -Force
$txt = [IO.File]::ReadAllText($mf)
$perms = @('INTERNET','ACCESS_NETWORK_STATE','ACCESS_WIFI_STATE','CAMERA','RECORD_AUDIO','MODIFY_AUDIO_SETTINGS',
  'ACCESS_COARSE_LOCATION','ACCESS_FINE_LOCATION','BLUETOOTH','BLUETOOTH_CONNECT','POST_NOTIFICATIONS','VIBRATE','WAKE_LOCK',
  'RECEIVE_BOOT_COMPLETED','FOREGROUND_SERVICE','FOREGROUND_SERVICE_CAMERA','FOREGROUND_SERVICE_MICROPHONE',
  'READ_MEDIA_IMAGES','READ_MEDIA_VIDEO','READ_MEDIA_AUDIO','READ_EXTERNAL_STORAGE','WRITE_EXTERNAL_STORAGE')
$add = ''
foreach ($p in $perms) {
  if ($txt -notmatch [regex]::Escape('"android.permission.' + $p + '"')) {
    $add += '    <uses-permission android:name="android.permission.' + $p + '" />' + "`r`n"
    Write-Host "  + $p"
  }
}
if ($add) {
  $idx = $txt.LastIndexOf('</manifest>')
  if ($idx -lt 0) { throw "Could not find </manifest> in AndroidManifest.xml" }
  $txt = $txt.Insert($idx, $add)
  [IO.File]::WriteAllText($mf, $txt, $utf8)
} else { Write-Host "  all permissions already present" }

# ---------- 4. Java 21 for Gradle ----------
Step "4/6  Java (JDK 21) for Gradle"
$gp = Join-Path $PSScriptRoot 'android\gradle.properties'
$gtxt = ''
if (Test-Path $gp) { $gtxt = [IO.File]::ReadAllText($gp) }
if ($gtxt -match '(?m)^org\.gradle\.java\.home=(.*)$') {
  Write-Host "already set: org.gradle.java.home=$($Matches[1])"
} else {
  $jdk = Get-ChildItem 'C:\Program Files\Eclipse Adoptium' -Directory -ErrorAction SilentlyContinue | Where-Object Name -like 'jdk-21*' | Select-Object -First 1
  if (-not $jdk) { throw "JDK 21 not found. Run: winget install EclipseAdoptium.Temurin.21.JDK   then open a NEW PowerShell window and run this script again." }
  Add-Content $gp ("`r`norg.gradle.java.home=" + $jdk.FullName.Replace('\', '/'))
  Write-Host "set org.gradle.java.home=$($jdk.FullName)"
}

# ---------- 5. Web build (only if missing) + Capacitor sync ----------
Step "5/6  Capacitor sync"
if (-not (Test-Path 'dist\client')) { Write-Host "dist\client missing -> running npm run build"; npm run build; if ($LASTEXITCODE -ne 0) { throw "npm run build failed" } }
npx cap sync android
if ($LASTEXITCODE -ne 0) { throw "npx cap sync android failed" }
$synced = Get-Content 'android\app\src\main\assets\capacitor.config.json' -Raw
if ($synced -notmatch 'https://stooorna\.com') { throw "Synced config has no server.url. Something is overriding capacitor.config.json - send me the output of: Get-ChildItem -Filter 'capacitor.config*'" }
Write-Host "synced config has server.url = https://stooorna.com  (login will use the live site)"

# ---------- 6. Build the APK ----------
Step "6/6  Building APK"
Push-Location android
.\gradlew.bat --stop | Out-Null
.\gradlew.bat assembleDebug
$code = $LASTEXITCODE
Pop-Location
if ($code -ne 0) { throw "Gradle build failed (see the error above)." }

$apk = Join-Path $PSScriptRoot 'android\app\build\outputs\apk\debug\app-debug.apk'
Copy-Item $apk (Join-Path $PSScriptRoot 'Stooorna.apk') -Force
Write-Host ""
Write-Host "DONE. APK: $PSScriptRoot\Stooorna.apk" -ForegroundColor Green
explorer $PSScriptRoot
